// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amountA, uint256 amountB) public {
        vm.assume(amountA <= VALUE_CAP);
        vm.assume(amountB <= VALUE_CAP);
        vm.assume(amountA > 0 && amountB > 0);
        vm.assume(amountA + amountB > amountA && amountA + amountB > amountB);
        address actor = address(0xABCD);
        vm.deal(actor, amountA + amountB);

        vm.prank(actor);
        (bool okA,) = payable(address(c)).call{value: amountA}("");
        require(okA, "first deposit failed");
        vm.prank(actor);
        (bool okB,) = payable(address(c)).call{value: amountB}("");
        require(okB, "second deposit failed");

        assertTrue(c.depositsCount() == 2 && address(c).balance == amountA + amountB);
    }
}
